-- 新增 SRM 路由规则号段枚举 CHUNK_SRM_NUMBER_RANGE（模块 CHUNK_SRM，下拉选项）：初版 200 个主流号段。
-- value 是不含加号的国际前缀，供路由规则直接匹配；国家、运营商和分类放在 json。
-- 回滚：DELETE FROM `tb_skyline_chunk` WHERE `key_id` BETWEEN 1024320 AND 1024519 AND `type` = 'CHUNK_SRM_NUMBER_RANGE';
--       DELETE FROM `tb_skyline_chunk_module` WHERE `key_id` = 1006 AND `type` = 'CHUNK_SRM_NUMBER_RANGE';

ALTER TABLE `tb_skyline_chunk_module`
    MODIFY COLUMN `type` varchar(128) NOT NULL COMMENT '枚举类型编码：CHUNK_SKYLINE_USER_POST=用户岗位（Skyline 账号岗位，仅一级枚举项，适用于普通下拉选择）；CHUNK_SKYLINE_USER_LEVEL=用户职级（Skyline 账号职级，P1-P8 专业序列、M1-M8 管理序列，仅一级枚举项）；CHUNK_SKYLINE_CONTACT_TYPE=联系方式（系统通用联系方式类型，仅一级枚举项）；CHUNK_CRM_USER_SOURCE=客户注册来源（CRM 客户注册来源，仅一级枚举项）；CHUNK_SRM_USER_SOURCE=供应商注册来源（SRM 供应商注册来源，初始数据复制自客户注册来源）；CHUNK_SRM_SIMBANK_MODEL=设备型号（SRM SIMBANK 设备型号，仅一级枚举项）；CHUNK_SRM_NUMBER_RANGE=号段码（SRM 路由规则号段码）';

ALTER TABLE `tb_skyline_chunk`
    MODIFY COLUMN `type` varchar(128) NOT NULL COMMENT '枚举类型编码：CHUNK_SKYLINE_USER_POST=用户岗位（Skyline 账号岗位，仅一级枚举项，适用于普通下拉选择）；CHUNK_SKYLINE_USER_LEVEL=用户职级（Skyline 账号职级，P1-P8 专业序列、M1-M8 管理序列，仅一级枚举项）；CHUNK_SKYLINE_CONTACT_TYPE=联系方式（系统通用联系方式类型，仅一级枚举项）；CHUNK_CRM_USER_SOURCE=客户注册来源（CRM 客户注册来源，仅一级枚举项）；CHUNK_SRM_USER_SOURCE=供应商注册来源（SRM 供应商注册来源，初始数据复制自客户注册来源）；CHUNK_SRM_SIMBANK_MODEL=设备型号（SRM SIMBANK 设备型号，仅一级枚举项）；CHUNK_SRM_NUMBER_RANGE=号段码（SRM 路由规则号段码）';

INSERT INTO `tb_skyline_chunk_module` (`key_id`, `module`, `type`, `name`, `kind`, `remark`, `create_by`, `modify_by`)
SELECT 1006, 'CHUNK_SRM', 'CHUNK_SRM_NUMBER_RANGE', '号段码', 'select', 'SRM 路由规则号段码，初版 200 个主流号段，value 为不含加号的国际前缀', '0', '0'
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `tb_skyline_chunk_module` WHERE `key_id` = 1006 OR `type` = 'CHUNK_SRM_NUMBER_RANGE');

